<?php namespace App\Livewire\Admin; use App\Models\Order; use App\Models\Stall; use App\Models\User; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class Dashboard extends Component { public function render() { return view('livewire.admin.dashboard', ['totalUsers' => User::count(), 'totalStalls' => Stall::count(), 'totalOrders' => Order::count(), 'activeOrders' => Order::whereIn('status', ['Pending', 'Preparing', 'Ready'])->count(), 'recentOrders' => Order::with(['stall', 'user'])->latest()->take(10)->get()]); } }